#include <bitset>
#include <iostream>

int main() {
    std::bitset<8> b("10101010");

    // Non-const access returns the proxy reference
    b[0] = true;        // Use operator=(bool)
    b[1].flip();        // Use flip() on the proxy

    // Read access uses operator bool() const
    bool val = b[7]; 

    // Check state
    std::cout << b << "\n"; // Output: 11101011

    // DANGER: Accessing index 8 (UB)
    // bool bad_val = b[8]; 
}
